CREATE TABLE "temporary_ad_bypass_entries" (
  id INTEGER PRIMARY KEY NOT NULL,
  ad_bypass INTEGER NOT NULL,
  ad_bypass_granted_at INTEGER,
  qualified_days INTEGER NOT NULL,
  send_count INTEGER NOT NULL,
  counted_at INTEGER NOT NULL,
  qualified_at INTEGER,
  CONSTRAINT temporary_whitelist_id CHECK (id <> 0),
  CONSTRAINT temporary_whitelist_flag CHECK (ad_bypass IN (0, 1)),
  CONSTRAINT temporary_whitelist_timestamp CHECK (
    (ad_bypass = 1 AND ad_bypass_granted_at IS NOT NULL) OR
    (ad_bypass = 0 AND ad_bypass_granted_at IS NULL)
  ),
  CONSTRAINT temporary_whitelist_day_count CHECK (
    qualified_days BETWEEN 0 AND 7 AND
    (ad_bypass = 1 OR qualified_days = 0)
  ),
  CONSTRAINT temporary_whitelist_send_count CHECK (send_count >= 1),
  CONSTRAINT temporary_whitelist_counted_at CHECK (counted_at >= 0),
  CONSTRAINT temporary_whitelist_qualified_at CHECK (
    (qualified_at IS NULL AND send_count <= 7) OR
    (qualified_at BETWEEN 0 AND counted_at AND send_count > 7 AND qualified_days >= 1)
  ),
  CONSTRAINT temporary_whitelist_granted_at CHECK (
    ad_bypass_granted_at IS NULL OR
    (ad_bypass_granted_at BETWEEN 0 AND counted_at AND
     (qualified_at IS NULL OR ad_bypass_granted_at <= qualified_at))
  )
) STRICT;
INSERT INTO temporary_ad_bypass_entries VALUES (99, 0, NULL, 0, 1, 1000, NULL);
